using Khazar.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Khazar.Infrastructure.Persistence.Configurations;

public sealed class CategoryConfiguration : IEntityTypeConfiguration<Category>
{
    public const string NameIndexName = "IX_Categories_Name";
    public const string SlugIndexName = "IX_Categories_Slug";

    public void Configure(EntityTypeBuilder<Category> builder)
    {
        builder.ToTable("Categories");

        builder.HasKey(c => c.Id);
        // Ids are generated by the domain (BaseEntity), not by the database.
        builder.Property(c => c.Id).ValueGeneratedNever();

        builder.Property(c => c.Name).IsRequired().HasMaxLength(Category.MaxNameLength);
        builder.Property(c => c.Label).IsRequired().HasMaxLength(Category.MaxLabelLength);
        builder.Property(c => c.Slug).IsRequired().HasMaxLength(Category.MaxSlugLength);

        builder.HasIndex(c => c.Name).IsUnique().HasDatabaseName(NameIndexName);
        builder.HasIndex(c => c.Slug).IsUnique().HasDatabaseName(SlugIndexName);
    }
}
